import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":null}'),n={name:"faq.md"};function r(o,e,h,l,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-astra" tabindex="-1">What is ASTRA? <a class="header-anchor" href="#what-is-astra" aria-label="Permalink to &quot;What is ASTRA?&quot;">​</a></h3><p>ASTRA (Adaptive Spectrum Threat Recognition &amp; Analysis) is a desktop application that schedules the scan pattern of an Electronic Support receiver. It decides <strong>which frequency band to listen to at every instant</strong> using machine learning, with zero prior intelligence on emitters.</p><h3 id="is-astra-operational-equipment" tabindex="-1">Is ASTRA operational equipment? <a class="header-anchor" href="#is-astra-operational-equipment" aria-label="Permalink to &quot;Is ASTRA operational equipment?&quot;">​</a></h3><p>No. ASTRA is a <strong>simulation-based research prototype</strong> for Smart India Hackathon 2026. It ships with a physically motivated simulated RF environment so it runs anywhere with no hardware.</p><h3 id="does-astra-transmit-or-jam" tabindex="-1">Does ASTRA transmit or jam? <a class="header-anchor" href="#does-astra-transmit-or-jam" aria-label="Permalink to &quot;Does ASTRA transmit or jam?&quot;">​</a></h3><p>No. ASTRA is a <strong>passive</strong> system. It only listens. It never transmits, jams, or connects to any classified system.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="does-closing-the-app-window-stop-the-service" tabindex="-1">Does closing the app window stop the service? <a class="header-anchor" href="#does-closing-the-app-window-stop-the-service" aria-label="Permalink to &quot;Does closing the app window stop the service?&quot;">​</a></h3><p>Use <strong>File → Exit</strong> for a clean shutdown. The console window also stops the service when closed.</p><h3 id="can-several-windows-share-one-service" tabindex="-1">Can several windows share one service? <a class="header-anchor" href="#can-several-windows-share-one-service" aria-label="Permalink to &quot;Can several windows share one service?&quot;">​</a></h3><p>Yes — open additional browser tabs to the printed URL. All views stay in sync because state lives server-side.</p><h3 id="is-any-data-sent-to-the-internet" tabindex="-1">Is any data sent to the internet? <a class="header-anchor" href="#is-any-data-sent-to-the-internet" aria-label="Permalink to &quot;Is any data sent to the internet?&quot;">​</a></h3><p>No. Networking is loopback except an optional HuggingFace fetch inside Dataset Studio, which falls back offline.</p><h2 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h2><h3 id="where-do-the-numbers-come-from" tabindex="-1">Where do the numbers come from? <a class="header-anchor" href="#where-do-the-numbers-come-from" aria-label="Permalink to &quot;Where do the numbers come from?&quot;">​</a></h3><p>Experiments over stored seeds. Re-run the suite to reproduce byte-for-byte:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ewsmart.experiments</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="why-does-receiver-b-exist" tabindex="-1">Why does Receiver B exist? <a class="header-anchor" href="#why-does-receiver-b-exist" aria-label="Permalink to &quot;Why does Receiver B exist?&quot;">​</a></h3><p>Controlled comparison. Identical battlefields make the scanning strategy the only variable. Any difference in outcome is attributable to strategy alone.</p><h3 id="what-kpps-does-smartscan-satisfy" tabindex="-1">What KPPs does SmartScan satisfy? <a class="header-anchor" href="#what-kpps-does-smartscan-satisfy" aria-label="Permalink to &quot;What KPPs does SmartScan satisfy?&quot;">​</a></h3><ol><li><strong>Threat coverage ≥ 90%</strong> — finds 95%+ of hostile emitters</li><li><strong>Prediction accuracy ≥ 50%</strong> — predicts at 62%+ accuracy</li><li><strong>False alarm rate ≤ 5×10⁻⁴/slot</strong> — well within operator limits</li></ol><h3 id="why-is-ucb-bandit-not-mission-capable-despite-high-reward" tabindex="-1">Why is UCB bandit not mission-capable despite high reward? <a class="header-anchor" href="#why-is-ucb-bandit-not-mission-capable-despite-high-reward" aria-label="Permalink to &quot;Why is UCB bandit not mission-capable despite high reward?&quot;">​</a></h3><p>UCB bandit achieves the highest raw reward by camping on the single most productive band. But it <strong>misses 46% of all threats</strong> — it never sweeps for new or rare emitters. Missing nearly half the threats is unacceptable regardless of reward.</p><h3 id="how-does-counter-esm-evasion-work" tabindex="-1">How does Counter-ESM evasion work? <a class="header-anchor" href="#how-does-counter-esm-evasion-work" aria-label="Permalink to &quot;How does Counter-ESM evasion work?&quot;">​</a></h3><p>Evasive emitters track consecutive interceptions. After 3+ consecutive intercepts, they shift their rotation phase or swap to a new frequency hop-set. The RF environment dynamically updates the truth matrix to reflect the new behaviour.</p><h3 id="what-is-a-dnd-token" tabindex="-1">What is a DND token? <a class="header-anchor" href="#what-is-a-dnd-token" aria-label="Permalink to &quot;What is a DND token?&quot;">​</a></h3><p>&quot;Do Not Disturb&quot; — when a receiver has a confirmed phase-lock on a band, it broadcasts a DND token. Other team members remove that band from their selection pools, ensuring zero redundancy.</p>',29)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
